# Mercado Livre — POST /oauth/token
import os
import random
import time

import requests

BASE = "https://api.mercadolibre.com"
CLIENT_ID = os.environ["ML_CLIENT_ID"]          # <<SEU_CLIENT_ID>>
CLIENT_SECRET = os.environ["ML_CLIENT_SECRET"]  # <<SEU_CLIENT_SECRET>>
tokens = {"access": os.environ.get("ML_ACCESS_TOKEN"), "refresh": os.environ["ML_REFRESH_TOKEN"]}


def renovar_token():
    """refresh_token é de uso único: grave o novo valor no seu cofre antes de continuar."""
    r = requests.post(BASE + "/oauth/token", timeout=30, headers={"accept": "application/json"},
                      data={"grant_type": "refresh_token", "client_id": CLIENT_ID,
                            "client_secret": CLIENT_SECRET, "refresh_token": tokens["refresh"]})
    r.raise_for_status()
    novo = r.json()
    tokens["access"], tokens["refresh"] = novo["access_token"], novo["refresh_token"]


def chamar(metodo, caminho, params=None, corpo=None, headers=None, tentativas=6):
    for n in range(tentativas):
        if not tokens["access"]:
            renovar_token()
        h = {"Authorization": "Bearer " + tokens["access"], "Accept": "application/json", **(headers or {})}
        r = requests.request(metodo, BASE + caminho, params=params, json=corpo, headers=h, timeout=60)
        if r.status_code == 401:
            tokens["access"] = None          # vence em 6 h: renova e repete
            continue
        if r.status_code == 429:
            time.sleep(min(60, 2 ** n) + random.random())   # backoff com jitter
            continue
        if r.status_code >= 400:
            raise RuntimeError(f"Mercado Livre HTTP {r.status_code}: {r.text[:300]}")
        return r.json() if r.content else None
    raise RuntimeError("tentativas esgotadas")


def pegar(dado, caminho):
    for parte in (caminho or "").split("."):
        if not parte or parte == "[]":
            continue
        dado = (dado or {}).get(parte) if isinstance(dado, dict) else None
    return dado


if __name__ == "__main__":
    renovar_token()
    print("token renovado; grave tokens['refresh'] no cofre")

