// Mercado Livre — POST /oauth/token (fetch nativo, Node 18+)
const BASE = "https://api.mercadolibre.com";
const CLIENT_ID = process.env.ML_CLIENT_ID!;          // <<SEU_CLIENT_ID>>
const CLIENT_SECRET = process.env.ML_CLIENT_SECRET!;  // <<SEU_CLIENT_SECRET>>
const tokens = { access: process.env.ML_ACCESS_TOKEN ?? "", refresh: process.env.ML_REFRESH_TOKEN! };
const espera = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function renovarToken(): Promise<void> {
  // refresh_token de uso único: grave o novo no cofre antes de seguir
  const r = await fetch(`${BASE}/oauth/token`, {
    method: "POST",
    headers: { accept: "application/json", "content-type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ grant_type: "refresh_token", client_id: CLIENT_ID, client_secret: CLIENT_SECRET, refresh_token: tokens.refresh }),
  });
  if (!r.ok) throw new Error(`renovação falhou: HTTP ${r.status} ${await r.text()}`);
  const d: any = await r.json();
  tokens.access = d.access_token;
  tokens.refresh = d.refresh_token;
}

async function chamar(metodo: string, caminho: string, params: Record<string, string> = {}, corpo?: unknown, extra: Record<string, string> = {}): Promise<any> {
  for (let n = 0; n < 6; n++) {
    if (!tokens.access) await renovarToken();
    const qs = new URLSearchParams(params).toString();
    const r = await fetch(`${BASE}${caminho}${qs ? "?" + qs : ""}`, {
      method: metodo,
      headers: { Authorization: `Bearer ${tokens.access}`, Accept: "application/json", ...(corpo ? { "Content-Type": "application/json" } : {}), ...extra },
      body: corpo ? JSON.stringify(corpo) : undefined,
    });
    if (r.status === 401) { tokens.access = ""; continue; }
    if (r.status === 429) { await espera(Math.min(60_000, 2 ** n * 1000) + Math.random() * 1000); continue; }
    if (!r.ok) throw new Error(`Mercado Livre HTTP ${r.status}: ${(await r.text()).slice(0, 300)}`);
    return r.status === 204 ? null : r.json();
  }
  throw new Error("tentativas esgotadas");
}

const pegar = (d: any, c: string | null) => (c ?? "").split(".").filter((p) => p && p !== "[]").reduce((a, p) => (a && typeof a === "object" ? a[p] : undefined), d);

renovarToken().then(() => console.log("token renovado; grave tokens.refresh no cofre"));

