      headers: { Authorization: `Bearer ${tokens.access}`, Accept: "application/json", ...(corpo ? { "Content-Type": "application/json" } : {}), ...extra },
      body: corpo ? JSON.stringify(corpo) : undefined,
    });
    if (r.status === 401) { tokens.access = ""; continue; }
    if (r.status === 429) { await espera(Math.min(60_000, 2 ** n * 1000) + Math.random() * 1000); continue; }
    if (!r.ok) throw new Error(`Mercado Livre HTTP ${r.status}: ${(await r.text()).slice(0, 300)}`);
    return r.status === 204 ? null : r.json();
  }
  throw new Error("tentativas esgotadas");
}

const pegar = (d: any, c: string | null) => (c ?? "").split(".").filter((p) => p && p !== "[]").reduce((a, p) => (a && typeof a === "object" ? a[p] : undefined), d);

async function main() {
  const caminho = `/missed_feeds`;
  const params: Record<string, string> = {"app_id": "<<SEU_CLIENT_ID>>", "topic": "orders_v2", "offset": "0", "limit": "10"};
  const extra: Record<string, string> = {};
  const tamanho = Number(params["limit"] ?? 50);
  const linhas: any[] = [];
  for (let deslocamento = 0; ; deslocamento += tamanho) {
    const d = await chamar("GET", caminho, { ...params, "offset": String(deslocamento), "limit": String(tamanho) }, undefined, extra);
    const lote: any[] = pegar(d, "messages") ?? [];
    linhas.push(...lote);
    if (lote.length < tamanho) break;
  }
  console.log(`${linhas.length} registros`);
}
main().catch((e) => { console.error(e); process.exit(1); });
